/**
 * One bounded marking pass, and what is left after it.
 *
 * `remaining` is what lets the caller decide to ask again: a pass is
 * capped by a deadline and a small batch, so finishing a four-task
 * writing section normally takes more than one call.
 */
export interface WritingGradeRunResult {
  graded: number;
  /**
     * Runs that errored. Each released its credit, so the learner paid
     * nothing and the essay is still there to retry (R-09).
     */
  failed: number;
  /** Essays in this attempt still QUEUED or GRADING. */
  remaining: number;
  /**
     * False when this deployment has no grading provider configured.
     * Reported rather than raised: it is an operator's fact, not the
     * learner's error, and a caller that re-sends until `remaining`
     * reaches zero has to be able to stop.
     */
  available: boolean;
}
